<?php
function lop_bulk_toolbar(string $section,bool $enabled): void {
    echo '<section class="dbt-card lop-bulk"><div><h2>Setujui sekaligus</h2><p>Kelompok siswa, nama komponen, pembayaran, dan tabungan yang cocok diproses bersama. Saldo berselisih cukup dikoreksi per rekening.</p></div><div class="legacy-actions"><form method="post">';lop_form_hidden('bulk_preview');
    echo '<input type="hidden" name="scope" value="all"><button class="dbt-button dbt-button-primary" '.($enabled?'':'disabled').'>'.legacy_ui_icon('check').' Setujui Semua Data</button></form>';
    $scope=['groups'=>'students','people'=>'students','components'=>'components','savings'=>'savings','confirm'=>'payments'][$section]??null;
    $label=['students'=>'Setujui Semua Siswa & Kelompok','components'=>'Setujui Semua Komponen','savings'=>'Setujui Tabungan yang Cocok','payments'=>'Setujui Aturan Pembayaran'][$scope]??'';
    if($scope){echo '<form method="post">';lop_form_hidden('bulk_preview');echo '<input type="hidden" name="scope" value="'.$scope.'"><button class="dbt-button" '.($enabled?'':'disabled').'>'.loe($label).'</button></form>';}
    echo '</div><p class="legacy-note">Persetujuan ini menyiapkan draf dan simulasi. Pemindahan ke database dilakukan setelah konfirmasi migrasi terakhir.</p></section>';
}
?>
<?php if($bulkConfirmation): $bulk=$bulkConfirmation;
$titles=['all'=>'Setujui Seluruh Data yang Siap?','students'=>'Sahkan Siswa dan Kelompok?','components'=>'Sahkan Komponen Pembayaran?','savings'=>'Sahkan Tabungan yang Cocok?','payments'=>'Sahkan Aturan Pembayaran?'];
