<?php if($bulk['new_masters']): ?><details><summary><?= count($bulk['new_masters']) ?> usulan komponen baru</summary><ul class="lop-confirm-list"><?php foreach($bulk['new_masters'] as $master): ?><li><strong><?= loe($master['name']) ?></strong><span>Nonaktif<?= !empty($master['tariff_pending'])?' — Tarif belum ditetapkan':'' ?></span></li><?php endforeach; ?></ul></details><?php endif; ?>
